{
  "name": "调试端口",
  "name_en": "Debug Port",
  "manufacturer": "",
  "description": "用于开发和测试的虚拟调试通信端口，可模拟连接开启与关闭、缓冲区数据读写以及简单的回显处理，常用于验证实验室软件中的通信流程和数据收发逻辑。",
  "description_en": "A virtual debug communication port used for development and testing. It simulates opening and closing a connection, buffered data read/write operations, and simple echo-style processing for validating laboratory communication workflows and data transfer logic.",
  "actions": [
    {
      "action_name": "isOpen",
      "description": "获取端口是否已打开",
      "description_en": "get whether the port is open"
    },
    {
      "action_name": "auto-open",
      "description": "打开调试端口连接。",
      "description_en": "Open the debug port connection."
    },
    {
      "action_name": "auto-close",
      "description": "关闭调试端口连接。",
      "description_en": "Close the debug port connection."
    },
    {
      "action_name": "auto-bytesAvailable",
      "description": "查询当前可读取的字节数。",
      "description_en": "Get the number of bytes currently available to read."
    },
    {
      "action_name": "auto-flush",
      "description": "刷新端口缓冲区。",
      "description_en": "Flush the port buffers."
    },
    {
      "action_name": "auto-readData",
      "description": "从调试端口读取指定长度的数据。",
      "description_en": "Read a specified amount of data from the debug port."
    },
    {
      "action_name": "auto-writeData",
      "description": "向调试端口写入数据。",
      "description_en": "Write data to the debug port."
    },
    {
      "action_name": "auto-writeToOutputBuffer",
      "description": "将数据写入指定的输出缓冲区。",
      "description_en": "Write data to the specified output buffer."
    },
    {
      "action_name": "auto-processInputBuffers",
      "description": "处理指定输入缓冲区中的数据，默认执行回显。",
      "description_en": "Process data in the specified input buffer, using echo behavior by default."
    }
  ],
  "tag_hints": [
    "debug communication",
    "virtual port",
    "echo testing",
    "buffered I/O",
    "instrument communication"
  ]
}

